exercises.starter:
function factorial(n) {
  // base case, then recurse toward it
}

exercises.solution:
function factorial(n) {
  if (n <= 1) return 1
  return n * factorial(n - 1)
}

exercises.starter:
function sumTo(n) {
  // base case at 0, then add n to the sum of everything below it
}

exercises.solution:
function sumTo(n) {
  if (n <= 0) return 0
  return n + sumTo(n - 1)
}

exercises.starter:
function power(base, exp) {
  // base case when exp is 0, then recurse on exp - 1
}

exercises.solution:
function power(base, exp) {
  if (exp === 0) return 1
  return base * power(base, exp - 1)
}

exercises.starter:
function sumArray(arr) {
  // base case for the empty array, then first element plus the sum of the rest
}

exercises.solution:
function sumArray(arr) {
  if (arr.length === 0) return 0
  return arr[0] + sumArray(arr.slice(1))
}

exercises.starter:
function sumNested(arr) {
  // sum numbers, recursing into any element that is itself an array
}

exercises.solution:
function sumNested(arr) {
  if (arr.length === 0) return 0
  const [first, ...rest] = arr
  const firstSum = Array.isArray(first) ? sumNested(first) : first
  return firstSum + sumNested(rest)
}
